import React, { useState, useEffect } from "react";
import axios from "axios";
import "./GroupManagement.css";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import StudentSidebar from "../components/StudentSidebar";

const GroupManagement = () => {
  const [members, setMembers] = useState([]);
  const [activityLogs, setActivityLogs] = useState([]);
  const [isAdmin, setIsAdmin] = useState(true); // Simulate admin for now

  const groupNo = "G-37";

  // Fetch group and student data on load
  useEffect(() => {
    const fetchData = async () => {
      try {
        const groupRes = await axios.get(`http://localhost:5000/api/group/${groupNo}`);
        const group = groupRes.data;

        const studentsRes = await axios.get("http://localhost:5000/api/student");
        const allStudents = studentsRes.data;

        const groupMembers = allStudents.filter(s => group.studentsRegno.includes(s.regNo));
        setMembers(
          groupMembers.map((student, idx) => ({
            id: idx + 1,
            regNo: student.regNo,
            name: student.studentName,
            role: "Unassigned", // Replace with actual role if stored
            email: `${student.regNo}@example.com`,
            profilePic: "https://via.placeholder.com/150",
            skills: "N/A",
          }))
        );
      } catch (err) {
        console.error("Error loading data", err);
      }
    };

    fetchData();
  }, []);

  // Update member role
  const updateRole = (id, newRole) => {
    const updatedMembers = members.map((member) =>
      member.id === id ? { ...member, role: newRole } : member
    );
    setMembers(updatedMembers);
    setActivityLogs([
      ...activityLogs,
      {
        id: activityLogs.length + 1,
        message: `Role updated for ${id}`,
        timestamp: new Date().toLocaleString(),
      },
    ]);
  };

  // Add new member to group
  const addMember = async () => {
    try {
      const newRegNo = prompt("Enter new member RegNo:");
      if (!newRegNo) return;

      if (members.some(m => m.regNo === newRegNo)) {
        alert("Member already in group");
        return;
      }

      const newMemberRes = await axios.get("http://localhost:5000/api/student");
      const student = newMemberRes.data.find(s => s.regNo === newRegNo);

      if (!student) {
        alert("Student not found");
        return;
      }

      await axios.put(`http://localhost:5000/api/group/${groupNo}`, {
        studentsRegno: [...members.map(m => m.regNo), newRegNo],
      });

      await axios.put(`http://localhost:5000/api/student/${student._id}`, {
        isGrouped: true,
      });

      const newMember = {
        id: members.length + 1,
        regNo: student.regNo,
        name: student.studentName,
        role: "Unassigned",
        email: `${student.regNo}@example.com`,
        profilePic: "https://via.placeholder.com/150",
        skills: "N/A",
      };

      setMembers([...members, newMember]);
      setActivityLogs([
        ...activityLogs,
        {
          id: activityLogs.length + 1,
          message: `Added member ${student.studentName}`,
          timestamp: new Date().toLocaleString(),
        },
      ]);
    } catch (err) {
      console.error("Error adding member", err);
    }
  };

  // Remove a member from the group
  const removeMember = async (id) => {
    try {
      const member = members.find(m => m.id === id);
      const updatedMembers = members.filter((m) => m.id !== id);

      await axios.put(`http://localhost:5000/api/group/${groupNo}`, {
        studentsRegno: updatedMembers.map(m => m.regNo),
      });

      const studentRes = await axios.get("http://localhost:5000/api/student");
      const student = studentRes.data.find(s => s.regNo === member.regNo);

      if (student) {
        await axios.put(`http://localhost:5000/api/student/${student._id}`, {
          isGrouped: false,
        });
      }

      setMembers(updatedMembers);
      setActivityLogs([
        ...activityLogs,
        {
          id: activityLogs.length + 1,
          message: `Removed member ${member.name}`,
          timestamp: new Date().toLocaleString(),
        },
      ]);
    } catch (err) {
      console.error("Error removing member", err);
    }
  };

  // Disband group completely
  const disbandGroup = async () => {
    try {
      const studentRes = await axios.get("http://localhost:5000/api/student");
      for (const member of members) {
        const student = studentRes.data.find(s => s.regNo === member.regNo);
        if (student) {
          await axios.put(`http://localhost:5000/api/student/${student._id}`, {
            isGrouped: false,
          });
        }
      }

      await axios.delete(`http://localhost:5000/api/group/${groupNo}`);

      setMembers([]);
      setActivityLogs([
        ...activityLogs,
        {
          id: activityLogs.length + 1,
          message: "Group disbanded",
          timestamp: new Date().toLocaleString(),
        },
      ]);

      alert("Group disbanded.");
    } catch (err) {
      console.error("Error disbanding group", err);
    }
  };

  return (
    <div className="group-management-container">
      <Navbar />
      <div className="content-wrapper">
        <StudentSidebar />
        <div className="main-content">
          <h1 className="title">Group Management</h1>

          {/* Group Information */}
          <div className="group-details">
            <h2>Group Details</h2>
            <div className="group-info">
              <p><strong>Group Number:</strong> {groupNo}</p>
              <p><strong>Project Title:</strong> Project Management System</p>
              <p><strong>Supervisor:</strong> Prof. Dr. Shazia Arshad</p>
            </div>
          </div>

          {/* Team Member Section */}
          <div className="profiles-section">
            <h2>Team Member Profiles</h2>
            <ul>
              {members.map((member) => (
                <li key={member.id} className="member-card">
                  <img src={member.profilePic} alt={member.name} className="profile-pic" />
                  <div className="member-info">
                    <p><strong>Name:</strong> {member.name}</p>
                    <p><strong>Role:</strong> {member.role}</p>
                    <p><strong>Email:</strong> {member.email}</p>
                    <p><strong>Skills:</strong> {member.skills}</p>

                    {isAdmin && (
                      <>
                        <label>
                          Update Role:
                          <select
                            value={member.role}
                            onChange={(e) => updateRole(member.id, e.target.value)}
                          >
                            <option value="Developer">Developer</option>
                            <option value="Tester">Tester</option>
                            <option value="Manager">Manager</option>
                          </select>
                        </label>
                        <button onClick={() => removeMember(member.id)} className="remove-button">
                          Remove Member
                        </button>
                      </>
                    )}
                  </div>
                </li>
              ))}
            </ul>

            {isAdmin && members.length < 4 && (
              <button onClick={addMember} className="add-member-button">
                Add Member
              </button>
            )}

            {isAdmin && (
              <button onClick={disbandGroup} className="disband-button">
                Disband Group
              </button>
            )}
          </div>

          {/* Communication Buttons */}
          <div className="communication-section">
            <h2>Group Communication Channels</h2>
            <div className="communication-buttons">
              <button onClick={() => window.open("https://zoom.us", "_blank")}>Start Zoom</button>
              <button onClick={() => window.open("https://meet.google.com", "_blank")}>Start Google Meet</button>
              <button onClick={() => window.open("https://teams.microsoft.com", "_blank")}>Start Teams</button>
            </div>
          </div>

          {/* Activity Logs */}
          <div className="logs-section">
            <h2>Activity Logs</h2>
            <ul>
              {activityLogs.map((log) => (
                <li key={log.id} className="log-item">
                  <span className="log-timestamp">{log.timestamp}</span> - {log.message}
                </li>
              ))}
            </ul>
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default GroupManagement;
